import type { CodeLine } from "../components/code-window.types";

export type HeroMedia = {
  /** what the hero shows besides the text */
  kind?: "none" | "image" | "backdrop" | "code" | "cluster";
  /** side of the media in the split layout */
  side?: "end" | "start";
  /** title of the code window */
  codeTitle?: string;
  /** prompt line of the code window */
  prompt?: string;
  /** lines of the code window */
  lines?: CodeLine[];
};
